command:
set +e
set -uo pipefail
# spawn runs task commands under bash -e; `set -uo pipefail` does not clear it (spawn#707).
export PATH=/opt/conda/bin:$PATH TMPDIR=/tmp HOME=/tmp
cd /tmp
echo 'ff807f3ecc446d61346a2b0dd629c6eb6673c316b718d3d45238e015fcdc8f97  prep-genome.sh' | sha256sum -c || { echo 'FAIL: prep-genome.sh does not match its pin'; exit 1; }
echo '5874ca5098bb98b88d3c9e62ea0b728681ee0d4446ca43977dea3b2a178c2913  prep-chunk.sh' | sha256sum -c || { echo 'FAIL: prep-chunk.sh does not match its pin'; exit 1; }
bash prep-genome.sh > prep-genome.log 2>&1
RC=$?
cat prep-genome.log
test "$RC" = 0 || { echo 'FAIL: prep failed'; exit 1; }
grep -q 'PREP GENOME OK' prep-genome.log || { echo 'FAIL: no completion sentinel'; exit 1; }
echo DONE
